  ?point a br:Electric_Power ; br:isPointOf ?a .
  FILTER(CONTAINS(str(?a), "AHU03"))
}

SELECT ?point ?tsid WHERE {
  ?point ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?tsid .
  FILTER(CONTAINS(str(?point), "AHU03"))
